client_script:
// --- Skip Frappe's generic hidden "success page" detour after Save: always land
//     straight back on the real document (full reload), where the next-step panel below
//     renders immediately instead of a bare "Submitted"-style message.
if (frappe.web_form) {
  frappe.web_form.handle_success = function (r) {
    var route = this.route;
    var name = (r && r.name) || (this.doc && this.doc.name);
    if (name) {
      window.location.href = "/" + route + "/" + encodeURIComponent(name);
    } else {
      window.location.reload();
    }
  };
}

function getAttachField() {
  return document.querySelector('[data-fieldname="custom_signed_resignation"]');
}

function hideRawAttachFieldIfNew() {
  try {
    var wf = frappe.web_form;
    if (!wf) return;
    var el = getAttachField();
    if (el && !(wf.doc && wf.doc.name)) {
      el.style.display = "none";
    }
  } catch (e) { console.error(e); }
}

// IMPORTANT: this function must NEVER move or remove the real attach field node.
// Only elements it creates itself (ids prefixed resignation-) are added/removed.
function renderResignationCTA() {
  try {
    var wf = frappe.web_form;
    if (!wf) return;
    var doc = wf.doc;
    var existingPanel = document.getElementById("resignation-step-cta");
    var existingMarker = document.getElementById("resignation-step2-marker");

    if (!doc || !doc.name) {
      hideRawAttachFieldIfNew();
      if (existingPanel) existingPanel.remove();
      if (existingMarker) existingMarker.remove();
      return;
    }
    if (doc.exit_type !== "Resignation") return;
    var state = doc.workflow_state || "Draft";

    var formEl = document.querySelector("form.web-form");
    if (!formEl) return;
    var attachField = getAttachField();

    if (state !== "Draft") {
      if (existingPanel) existingPanel.remove();
      if (existingMarker) existingMarker.remove();
      if (attachField) attachField.style.display = "";
      return;
    }

    var hasLetter = !!doc.custom_signed_resignation;

    function stepRow(num, bodyEl, done) {
      var row = document.createElement("div");
      row.style.cssText = "display:flex;align-items:flex-start;gap:10px;margin-bottom:12px;";
      var badge = document.createElement("div");
      badge.textContent = done ? "\u2713" : String(num);
      badge.style.cssText = "flex:0 0 22px;height:22px;border-radius:50%;text-align:center;line-height:22px;font-size:12px;font-weight:600;color:#fff;background:" + (done ? "#52c41a" : "#595959") + ";";
      var body = document.createElement("div");
      body.style.cssText = "flex:1;";
      body.appendChild(bodyEl);
      row.appendChild(badge);
      row.appendChild(body);
      return row;
    }

    // Main panel: heading + Step 1 (download) + Step 2 placeholder (view mode only) or
    // Step 3 (submit). Never contains the real attach field node.
    var panel = document.createElement("div");
    panel.id = "resignation-step-cta";
    panel.style.cssText = "margin:0 0 16px 0;padding:16px 18px;border-radius:8px;border:1px solid #d9d9d9;background:#fafafa;";

    var heading = document.createElement("div");
    heading.textContent = "This request is still a draft and has not been sent to your manager.";
    heading.style.cssText = "font-weight:600;margin-bottom:14px;";
    panel.appendChild(heading);

    var s1 = document.createElement("div");
    var dl = document.createElement("a");
    dl.className = "btn btn-sm btn-default";
    dl.target = "_blank";
    dl.textContent = "Download Resignation Letter";
    dl.href = "/printview?doctype=Employee%20Exit&name=" + encodeURIComponent(doc.name) + "&format=Resignation%20Letter&no_letterhead=1";
    s1.appendChild(document.createElement("div")).textContent = "Optional: download the letter if you also want to sign it by hand.";
    s1.appendChild(dl);
    panel.appendChild(stepRow(1, s1, false));

    var usingInlineMarker = wf.in_edit_mode && attachField;

    if (!usingInlineMarker) {
      var s2 = document.createElement("div");
      var label2b = document.createElement("div");
      label2b.textContent = "Optional: attach a signed letter.";
      label2b.style.cssText = "margin-bottom:6px;";
      s2.appendChild(label2b);
      var editLink = document.createElement("a");
      editLink.className = "btn btn-sm btn-default";
      editLink.textContent = "Attach a Signed Letter (optional)";
      editLink.href = "/" + wf.route + "/" + encodeURIComponent(doc.name) + "/edit";
      s2.appendChild(editLink);
      panel.appendChild(stepRow(2, s2, hasLetter));
    }

    var s3 = document.createElement("div");
    if (false) { // signed letter is optional now; the system attaches a signed acknowledgement
      var waiting = document.createElement("div");
      waiting.style.color = "#8c8c8c";
      waiting.textContent = "Available once your signed letter is attached.";
      s3.appendChild(waiting);
    } else {
      var subBtn = document.createElement("button");
      subBtn.type = "button";
      subBtn.className = "btn btn-sm btn-primary";
      subBtn.id = "resignation-submit-btn";
      subBtn.textContent = "Submit Resignation Request";
      s3.appendChild(subBtn);
    }
    panel.appendChild(stepRow(usingInlineMarker ? 2 : 3, s3, false));

    if (existingPanel) existingPanel.remove();
    formEl.insertBefore(panel, formEl.firstChild);

    // Step 2 inline marker, placed right before the real attach field -- never touches
    // or moves the field itself, so it survives every future re-render.
    if (existingMarker) existingMarker.remove();
    if (usingInlineMarker) {
      var marker = document.createElement("div");
      marker.id = "resignation-step2-marker";
      marker.style.cssText = "display:flex;align-items:center;gap:8px;margin:4px 0 6px 0;font-weight:600;";
      var mbadge = document.createElement("div");
      mbadge.textContent = hasLetter ? "\u2713" : "1";
      mbadge.style.cssText = "flex:0 0 22px;height:22px;border-radius:50%;text-align:center;line-height:22px;font-size:12px;font-weight:600;color:#fff;background:" + (hasLetter ? "#52c41a" : "#595959") + ";";
      var mtext = document.createElement("div");
      mtext.textContent = "Optional: attach a signed letter below:";
      marker.appendChild(mbadge);
      marker.appendChild(mtext);
      attachField.parentElement.insertBefore(marker, attachField);
      attachField.style.display = "";
    }

    var btn = document.getElementById("resignation-submit-btn");
    if (btn) {
      btn.addEventListener("click", function () {
        btn.disabled = true;
        btn.textContent = "Submitting...";
        var currentVal = (wf.doc && wf.doc.custom_signed_resignation) || doc.custom_signed_resignation;
        var ensureSaved = currentVal
          ? frappe.call({ method: "frappe.client.set_value", args: { doctype: "Employee Exit", name: doc.name, fieldname: "custom_signed_resignation", value: currentVal } })
          : Promise.resolve();
        ensureSaved.then(function () {
          return frappe.call({ method: "submit_portal_resignation", args: { name: doc.name } });
        }).then(function (r) {
          var msg = (r && r.message) || {};
          frappe.msgprint(msg.message || "Submitted.");
          setTimeout(function () { window.location.href = "/" + wf.route + "/" + encodeURIComponent(doc.name); }, 900);
        }).catch(function () {
          btn.disabled = false;
          btn.textContent = "Submit Resignation Request";
        });
      });
    }
  } catch (e) {
    console.error("Resignation CTA error", e);
  }
}

hideRawAttachFieldIfNew();
setTimeout(renderResignationCTA, 150);
setTimeout(renderResignationCTA, 700);
if (frappe.web_form && frappe.web_form.events && frappe.web_form.events.on) {
  frappe.web_form.events.on("after_save", function () {
    setTimeout(renderResignationCTA, 150);
  });
}

// Web form view<->edit switches happen as client-side route changes, not full page
// reloads, so the initial calls above only cover the very first load. Poll for a path
// or edit-mode change and re-render after it settles.
(function () {
  var lastPath = window.location.pathname;
  var lastEditMode = frappe.web_form && frappe.web_form.in_edit_mode;
  function schedule() {
    setTimeout(hideRawAttachFieldIfNew, 150);
    setTimeout(renderResignationCTA, 300);
    setTimeout(renderResignationCTA, 700);
    setTimeout(renderResignationCTA, 1300);
  }
  setInterval(function () {
    var wf = frappe.web_form;
    var curEditMode = wf && wf.in_edit_mode;
    if (window.location.pathname !== lastPath || curEditMode !== lastEditMode) {
      lastPath = window.location.pathname;
      lastEditMode = curEditMode;
      schedule();
    }
  }, 300);
})();


// --- Portal resignation defaults: notice period, dates and reason list come from the
//     logged-in employee's record (web forms do not run fetch_from on the page).
(function () {
  var wf = frappe.web_form;
  if (!wf) return;
  var portalDefaults = null;

  function isNewDoc() { return !(wf.doc && wf.doc.name); }
  function canEdit() { return isNewDoc() || ((wf.doc.workflow_state || "Draft") === "Draft"); }

  function refreshLastWorkingDay() {
    if (!portalDefaults || !canEdit()) return;
    var start = wf.get_value("notice_date");
    var days = portalDefaults.notice_days || 0;
    if (start && days) {
      wf.set_value("last_working_day", frappe.datetime.add_days(start, days));
    }
  }

  function refreshReasons() {
    if (!portalDefaults) return;
    var field = wf.fields_dict && wf.fields_dict.custom_exit_reason;
    if (!field) return;
    var type = wf.get_value("exit_type") || "Resignation";
    var list = [];
    (portalDefaults.reasons || []).forEach(function (r) {
      if (r.exit_type === type || r.name === "Other (see comments)") list.push(r.name);
    });
    field.df.options = list;
    if (field.set_data) field.set_data(list);
    var current = wf.get_value("custom_exit_reason");
    if (current && list.indexOf(current) === -1 && canEdit()) wf.set_value("custom_exit_reason", "");
  }

  frappe.call({ method: "get_my_resignation_defaults" }).then(function (r) {
    portalDefaults = (r && r.message) || null;
    if (!portalDefaults) return;
    if (isNewDoc() && portalDefaults.open_exit) {
      var ox = portalDefaults.open_exit;
      var formEl = document.querySelector("form.web-form");
      if (formEl) {
        var box = document.createElement("div");
        box.id = "resignation-already-raised";
        box.style.cssText = "border:1px solid #b26a0033;background:#fff4e0;border-left:4px solid #b26a00;border-radius:8px;padding:14px 16px;margin-bottom:18px;";
        var h = document.createElement("div");
        h.style.cssText = "font-weight:600;color:#b26a00;font-size:14px;";
        h.textContent = "You already have a resignation request (" + ox.name + ") – Status: " + (ox.workflow_state || "Draft");
        var p = document.createElement("div");
        p.style.cssText = "color:#383838;font-size:13px;margin:4px 0 10px;";
        p.textContent = "A new request can only be raised if the previous one is Rejected.";
        var a = document.createElement("a");
        a.className = "btn btn-sm btn-default";
        a.href = "/" + wf.route + "/" + encodeURIComponent(ox.name);
        a.textContent = "View my resignation";
        box.appendChild(h); box.appendChild(p); box.appendChild(a);
        formEl.parentNode.insertBefore(box, formEl);
        formEl.style.display = "none";
      }
      document.querySelectorAll(".submit-btn, .discard-btn").forEach(function (el) { el.style.display = "none"; });
      return;
    }
    if (isNewDoc()) {
      if (!wf.get_value("exit_type")) wf.set_value("exit_type", "Resignation");
      if (!wf.get_value("notice_date")) wf.set_value("notice_date", portalDefaults.today);
      wf.set_value("custom_notice_period_days", portalDefaults.notice_days || 0);
      if (!portalDefaults.employee) {
        frappe.msgprint("No active employee record is linked to your login, so a resignation cannot be raised. Please contact HR.");
      } else if (!portalDefaults.notice_days) {
        frappe.msgprint("Your notice period is not set on your employee record yet. HR will confirm it after you submit.");
      }
    }
    refreshLastWorkingDay();
    refreshReasons();
  });

  wf.on("notice_date", function () { refreshLastWorkingDay(); });
  wf.on("exit_type", function () { refreshReasons(); });
})();


// --- Status banner + lock: once a resignation leaves Draft it is read-only for the employee.
(function () {
  var wf = frappe.web_form;
  if (!wf) return;
  var STATUS_INFO = {
    "Draft": ["#6c757d", "#f4f5f6", "Draft – not yet submitted. You can still edit this resignation."],
    "Pending Manager Approval": ["#b26a00", "#fff4e0", "Submitted and waiting for your manager's approval. It can no longer be edited."],
    "Pending HR Approval": ["#0b5cad", "#e8f1fc", "Approved by your manager and waiting for HR approval. It can no longer be edited."],
    "Approved": ["#1e7e34", "#e6f4ea", "Your resignation has been approved."],
    "Rejected": ["#b02a37", "#fde8ea", "Your resignation was not approved. Please contact HR for details."],
    "Exit Closed": ["#495057", "#eef0f2", "Your exit has been completed and closed."]
  };

  function applyStatus() {
    try {
      var doc = wf.doc || {};
      var formEl = document.querySelector("form.web-form") || document.querySelector(".web-form-container");
      var old = document.getElementById("resignation-status-banner");
      if (!doc.name || !formEl) { if (old) old.remove(); return; }
      var state = doc.workflow_state || "Draft";
      var info = STATUS_INFO[state] || ["#495057", "#eef0f2", ""];
      if (!old || old.getAttribute("data-state") !== state) {
        if (old) old.remove();
        var b = document.createElement("div");
        b.id = "resignation-status-banner";
        b.setAttribute("data-state", state);
        b.style.cssText = "border:1px solid " + info[0] + "33;background:" + info[1] + ";border-left:4px solid " + info[0] + ";border-radius:8px;padding:12px 14px;margin-bottom:18px;";
        var t = document.createElement("div");
        t.style.cssText = "font-weight:600;color:" + info[0] + ";font-size:14px;";
        t.textContent = "Status: " + state;
        var m = document.createElement("div");
        m.style.cssText = "color:#383838;font-size:13px;margin-top:3px;";
        m.textContent = info[2];
        b.appendChild(t); b.appendChild(m);
        formEl.insertBefore(b, formEl.firstChild);
      }
      if (state !== "Draft") {
        if (/\/edit\/?$/.test(window.location.pathname)) {
          window.location.href = "/" + wf.route + "/" + encodeURIComponent(doc.name);
          return;
        }
        document.querySelectorAll(".edit-button, a[href$='/edit'], .submit-btn, .discard-btn").forEach(function (el) { el.style.display = "none"; });
      }
    } catch (e) { console.error("Resignation status banner error", e); }
  }
  applyStatus();
  setInterval(applyStatus, 800);
})();
